function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // brain
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W / 2, H / 2, 100, 0, 2 * Math.PI);
  ctx.stroke();

  // blueberry
  ctx.fillStyle = 'blue';
  ctx.beginPath();
  ctx.arc(W / 2 + 120 + 50 * Math.sin(t), H / 2, 30, 0, 2 * Math.PI);
  ctx.fill();
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.stroke();

  // antioxidant
  ctx.fillStyle = 'green';
  ctx.font = '24px Arial';
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  ctx.fillText('Antioxidant', W / 2 + 150 + 50 * Math.sin(t), H / 2 - 50);

  // stick figure
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W / 2 - 150, H / 2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2 - 150, H / 2 + 20);
  ctx.lineTo(W / 2 - 150, H / 2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2 - 150, H / 2 + 50);
  ctx.lineTo(W / 2 - 120, H / 2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2 - 150, H / 2 + 50);
  ctx.lineTo(W / 2 - 180, H / 2 + 70);
  ctx.stroke();

  ctx.restore();
}
